/** static void CyclePalette(s16 *counter, s16 *palIdx) */
export function CyclePalette(counter: any, palIdx: any): any {
  let idx: any = null;
      if (++(counter) > 5)
      {
          if (++palIdx == ARRAY_COUNT(sPalettes) - 2)
              palIdx = 0;

          counter = 0;
      }
      idx = palIdx + 2;  
      LoadPalette(sPalettes[idx], BG_PLTT_ID(0), PLTT_SIZEOF(8));
}

